<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Projectile Motion Sandbox</title>
<style>
  body { font-family: sans-serif; display: flex; flex-direction: column; align-items: center; background-color: #f4f4f9; padding: 20px; }
  .card { background: white; padding: 20px; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); width: 100%; max-width: 800px; margin-bottom: 20px; }
  .controls { display: flex; flex-wrap: wrap; gap: 15px; margin-bottom: 15px; justify-content: center; }
  .control-group { display: flex; flex-direction: column; min-width: 150px; }
  label { font-weight: bold; margin-bottom: 5px; font-size: 0.9em; }
  input[type="range"] { width: 100%; }
  button { background-color: #007bff; color: white; border: none; padding: 10px 20px; border-radius: 5px; cursor: pointer; font-size: 1em; transition: background-color 0.2s; }
  button:hover { background-color: #0056b3; }
  canvas { background-color: #e0f7fa; border: 1px solid #ccc; border-radius: 4px; width: 100%; height: auto; display: block; }
  .legend { display: flex; justify-content: center; gap: 20px; margin-top: 10px; font-size: 0.9em; }
  .legend-item { display: flex; align-items: center; }
  .color-box { width: 15px; height: 15px; margin-right: 5px; border-radius: 3px; }
</style>
</head>
<body>

<div class="card">
  <h2 style="text-align: center; margin-top: 0;">Projectile Motion Sandbox</h2>
  <div class="controls">
    <div class="control-group">
      <label for="velocity">Initial Velocity (m/s): <span id="val-velocity">50</span></label>
      <input type="range" id="velocity" min="10" max="100" value="50">
    </div>
    <div class="control-group">
      <label for="angle">Launch Angle (degrees): <span id="val-angle">45</span></label>
      <input type="range" id="angle" min="0" max="90" value="45">
    </div>
    <div class="control-group">
      <label for="drag">Drag Coefficient (Cd): <span id="val-drag">0.00</span></label>
      <input type="range" id="drag" min="0" max="0.1" step="0.001" value="0.00">
      <small style="color: #666; font-size: 0.8em;">0.00 = Vacuum (Ideal)</small>
    </div>
    <div class="control-group" style="justify-content: flex-end;">
      <button id="fire-btn">Fire Projectile</button>
    </div>
  </div>
  <canvas id="simCanvas" width="700" height="400"></canvas>
  <div class="legend">
    <div class="legend-item"><div class="color-box" style="background-color: #007bff;"></div>Real Trajectory (with Drag)</div>
    <div class="legend-item"><div class="color-box" style="background-color: #aaa; border: 1px dashed #666; background: transparent;"></div>Ideal Trajectory (Vacuum)</div>
  </div>
</div>

<script>
  const canvas = document.getElementById('simCanvas');
  const ctx = canvas.getContext('2d');
  const vInput = document.getElementById('velocity');
  const aInput = document.getElementById('angle');
  const dInput = document.getElementById('drag');
  const fireBtn = document.getElementById('fire-btn');

  // Display values next to sliders
  vInput.oninput = () => document.getElementById('val-velocity').textContent = vInput.value;
  aInput.oninput = () => document.getElementById('val-angle').textContent = aInput.value;
  dInput.oninput = () => {
    const val = parseFloat(dInput.value).toFixed(3);
    document.getElementById('val-drag').textContent = val;
  };

  // Simulation parameters
  const g = 9.81; // Gravity (m/s^2)
  const dt = 0.05; // Time step (s)
  const scale = 5; // Pixels per meter

  function draw() {
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw ground
    ctx.fillStyle = '#4CAF50';
    ctx.fillRect(0, canvas.height - 20, canvas.width, 20);

    // Get parameters from inputs
    const v0 = parseFloat(vInput.value);
    const theta = parseFloat(aInput.value) * Math.PI / 180;
    const Cd = parseFloat(dInput.value);

    // --- Calculate Ideal Trajectory (No Drag) ---
    ctx.beginPath();
    ctx.strokeStyle = '#aaa';
    ctx.setLineDash([5, 5]);
    ctx.lineWidth = 2;

    let xIdeal = 0;
    let yIdeal = 0;
    let vxIdeal = v0 * Math.cos(theta);
    let vyIdeal = v0 * Math.sin(theta);

    ctx.moveTo(0, canvas.height - 20 - yIdeal * scale);

    while (yIdeal >= 0) {
      vxIdeal = vxIdeal; // No horizontal acceleration
      vyIdeal -= g * dt;

      xIdeal += vxIdeal * dt;
      yIdeal += vyIdeal * dt;

      if (yIdeal < 0) break;
      ctx.lineTo(xIdeal * scale, canvas.height - 20 - yIdeal * scale);
    }
    ctx.stroke();
    ctx.setLineDash([]); // Reset dash

    // --- Calculate Real Trajectory (With Drag) ---
    ctx.beginPath();
    ctx.strokeStyle = '#007bff';
    ctx.lineWidth = 3;

    let x = 0;
    let y = 0;
    let vx = v0 * Math.cos(theta);
    let vy = v0 * Math.sin(theta);
    const mass = 1; // Mass of the projectile (kg)

    ctx.moveTo(0, canvas.height - 20 - y * scale);

    while (y >= 0) {
      const v = Math.sqrt(vx*vx + vy*vy);

      // Drag force: Fd = (1/2) * rho * v^2 * Cd * A
      // We simplify constants into a single 'dragFactor' for simulation
      const dragFactor = 0.5 * 1.225 * Cd * 0.01; // rho=1.225 (air density), A=0.01 (area)
      const Fd = dragFactor * v * v;

      // Drag acts opposite to velocity
      const Fx = -Fd * (vx / v);
      const Fy = -Fd * (vy / v);

      // Acceleration: F = ma => a = F/m
      const ax = Fx / mass;
      const ay = -g + (Fy / mass);

      vx += ax * dt;
      vy += ay * dt;

      x += vx * dt;
      y += vy * dt;

      if (y < 0) break;

      // Stop drawing if out of bounds
      if (x * scale > canvas.width) break;

      ctx.lineTo(x * scale, canvas.height - 20 - y * scale);
    }
    ctx.stroke();

    // Draw projectile at start
    ctx.beginPath();
    ctx.fillStyle = '#333';
    ctx.arc(0, canvas.height - 20, 5, 0, Math.PI * 2);
    ctx.fill();
  }

  // Initial draw
  draw();

  // Re-draw on button click or input change
  fireBtn.addEventListener('click', draw);
  vInput.addEventListener('input', draw);
  aInput.addEventListener('input', draw);
  dInput.addEventListener('input', draw);

</script>
</body>
</html>
```

